cat > crypter.yara << 'EOF'
rule CrypterDetect {
  strings:
    $c1 = { 60 8B 74 24 04 8B 7C 24 08 }
    $c2 = "decrypt"
  condition:
    any of them
}
EOF

cat > section_name.yara << 'EOF'
import "pe"
rule SectionName {
  condition:
    for any section in pe.sections : ( section.name == ".upx0" or section.name == ".packed" )
}
EOF

cat > crc32.yara << 'EOF'
rule CRC32Match {
  condition:
    hash.crc32(0, filesize) == 0x12345678
}
EOF

cat > not_hex.yara << 'EOF'
rule NotHex {
  condition:
    uint32(0) != 0x5A4D and uint32(0) != 0x464C457F
}
EOF
